/**
 * Code samples of an API operation, ejected from docusaurus-theme-openapi-docs 4.7.1 and simplified.
 *
 * One row of tabs per language. A tab is either a code sample of the specification (x-codeSamples, matched by
 * label) or a variant generated by postman-code-generators, which follows the values entered in the request form.
 * The languages and their tabs, in order, are set in themeConfig.languageTabs:
 *
 *   {language: 'php', highlight: 'php', logoClass: 'php',
 *    tabs: [{sample: 'Joomla HttpFactory'}, {variant: 'curl', label: 'cURL'}]}
 *
 * `language` and `variant` are postman-code-generators keys. A sample tab is left out when an operation has no
 * sample with that label; a language without any tab is left out.
 */
import React, {useEffect, useState} from 'react';
import cloneDeep from 'lodash/cloneDeep';
import codegen from 'postman-code-generators';
import useDocusaurusContext from '@docusaurus/useDocusaurusContext';
import ApiCodeBlock from '@theme/ApiExplorer/ApiCodeBlock';
import buildPostmanRequest from '@theme/ApiExplorer/buildPostmanRequest';
import CodeTabs from '@theme/ApiExplorer/CodeTabs';
import {useTypedSelector} from '@theme/ApiItem/hooks';

const CONVERT_OPTIONS = {longFormat: false, followRedirect: true, trimRequestBody: true};

function CodeTab({children, hidden, className}) {
  return (
    <div role="tabpanel" className={className} hidden={hidden}>
      {children}
    </div>
  );
}

function GeneratedCode({language, variant, highlight, request}) {
  const [code, setCode] = useState('');
  useEffect(() => {
    codegen.convert(language, variant, request, CONVERT_OPTIONS, (error, snippet) => {
      setCode(error ? '' : snippet);
    });
  }, [language, variant, request]);
  return (
    <ApiCodeBlock language={highlight} className="openapi-explorer__code-block" showLineNumbers>
      {code}
    </ApiCodeBlock>
  );
}

/** Replace the credentials by placeholders, as the original component does. */
function maskAuth(auth) {
  const cloned = cloneDeep(auth);
  let placeholder;
  function clean(obj) {
    for (const key in obj) {
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        const comboAuthId = Object.keys(obj).join(' and ');
        const authOptions = cloned?.options?.[key] ?? cloned?.options?.[comboAuthId];
        placeholder = authOptions?.find((opt) => opt.key === key)?.name;
        obj[key] = clean(obj[key]);
      } else {
        obj[key] = `<${placeholder ?? key}>`;
      }
    }
    return obj;
  }
  return {...cloned, data: clean(cloned.data)};
}

export default function CodeSnippets({postman, codeSamples, maskCredentials = true}) {
  const {siteConfig} = useDocusaurusContext();
  const contentType = useTypedSelector((state) => state.contentType.value);
  const accept = useTypedSelector((state) => state.accept.value);
  const server = useTypedSelector((state) => state.server.value);
  const body = useTypedSelector((state) => state.body);
  const pathParams = useTypedSelector((state) => state.params.path);
  const queryParams = useTypedSelector((state) => state.params.query);
  const cookieParams = useTypedSelector((state) => state.params.cookie);
  const headerParams = useTypedSelector((state) => state.params.header);
  const auth = useTypedSelector((state) => state.auth);

  const request = buildPostmanRequest(postman, {
    queryParams,
    pathParams,
    cookieParams,
    contentType,
    accept,
    headerParams,
    body,
    server,
    auth: maskCredentials ? maskAuth(auth) : auth,
  });

  const languages = (siteConfig?.themeConfig?.languageTabs ?? [])
    .map((language) => ({
      ...language,
      tabs: (language.tabs ?? []).filter(
        (tab) => tab.variant || (codeSamples ?? []).some((sample) => sample.label === tab.sample),
      ),
    }))
    .filter((language) => language.tabs.length > 0);

  if (languages.length === 0) {
    return null;
  }

  return (
    <CodeTabs groupId="code-samples" lazy>
      {languages.map((language) => (
        <CodeTab
          value={language.language}
          label={language.label ?? language.language}
          key={language.language}
          attributes={{className: `openapi-tabs__code-item--${language.logoClass}`}}>
          <CodeTabs
            className="openapi-tabs__code-container-inner"
            groupId={`code-samples-${language.language}`}
            lazy>
            {language.tabs.map((tab) => {
              const value = tab.sample ?? `${language.language}-${tab.variant}`;
              return (
                <CodeTab
                  value={value}
                  label={tab.label ?? tab.sample ?? tab.variant}
                  key={value}
                  attributes={{className: 'openapi-tabs__code-item--variant'}}>
                  {tab.sample ? (
                    <ApiCodeBlock
                      language={language.highlight}
                      className="openapi-explorer__code-block"
                      showLineNumbers>
                      {codeSamples.find((sample) => sample.label === tab.sample).source}
                    </ApiCodeBlock>
                  ) : (
                    <GeneratedCode
                      language={language.language}
                      variant={tab.variant}
                      highlight={language.highlight}
                      request={request}
                    />
                  )}
                </CodeTab>
              );
            })}
          </CodeTabs>
        </CodeTab>
      ))}
    </CodeTabs>
  );
}
